    [DataEventHandler(tableStr(DMFEntityExportDetails), DataEventType::Inserted)]
    public static void DMFEntityExportDetails_onInserted(Common sender, DataEventArgs e)
    {
        DMFEntityExportDetails dmfEntityExportDetails = sender;
        DMFDefinitionGroup dmfDefinitionGroup = DMFDefinitionGroup::find(dmfEntityExportDetails.DefinitionGroup);

        if (dmfDefinitionGroup.OperationType == DMFOperationType::Export &&
            dmfDefinitionGroup.ProjectCategory == DMFProjectCategory::Integration &&
            dmfEntityExportDetails.RecId &&
            dmfEntityExportDetails.SampleFilePath )
        {
            if(DMFExecution::find(dmfEntityExportDetails.ExecutionId).GetExecutionSummaryStatus() == DMFExecutionSummaryStatus::Failed
                || DMFExecution::find(dmfEntityExportDetails.ExecutionId).GetExecutionSummaryStatus() == DMFExecutionSummaryStatus::Succeeded
                || DMFExecution::find(dmfEntityExportDetails.ExecutionId).GetExecutionSummaryStatus() == DMFExecutionSummaryStatus::PartiallySucceeded)
            {
                MET_AXDMFExportBusinessEvent businessEvent = MET_AXDMFExportBusinessEvent::newFromDMFEntityExportDetailsRecId(dmfEntityExportDetails.RecId);
                businessEvent.send();
            }
           
        }
    }
